package main
import("fmt";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz")
const src=`fun copy_forward(dst:^u8,src:^u8,n:u8)->u8 {var i:u8=0 while i<n {dst[i]=src[i] i=i+1} return i}
fun region_eq(src:^u8,arena:^u8,src_start:u16,arena_ptr:u16,len:u8)->u8 {var i:u8=0 while i<len {if src[src_start+i]!=arena[arena_ptr+1+i] {return 0} i=i+1} return 1}
fun other(n:u8)->u8 {var x:u8=0 while x<n {x=x+1} return x}`
func main(){for _,kind:=range []string{"clean","orphan","missingUnrelated","wrongKind","orphanSourceOrigin","policy"}{a,_:=nanz.Parse(src,"copy-region-review.nanz");b,_:=nanz.Parse(src,"copy-region-review.nanz");copies,regions,e:=hir.MixedCopyRegionSites(a);must(e);choice:=hir.MixedCopyRegionChoices{Copy:map[string]bool{copies[0]:true},Region:map[string]bool{regions[0]:true}};c,e:=hir.BuildProfileCompatibility(b,hir.ProfileContext{CompilerID:"review",SemanticsID:"review",TargetID:"review",WorkloadSHA256:"0123456789012345678901234567890123456789012345678901234567890123",HostsSHA256:"0123456789012345678901234567890123456789012345678901234567890123",Dependencies:b.SourceUnits});must(e);must(hir.ApplyMixedCopyRegionChoices(b,c,choice));switch kind{case "orphan":b.LoopLineage[&hir.Block{}]=hir.LoopLineage{SiteID:copies[0],Role:"fast",Rule:hir.ForwardCopyRule};case "missingUnrelated":delete(b.LoopLineage,b.FuncByName("other").Body.Body[1]);case "wrongKind":choice.Copy[regions[0]]=true;case "orphanSourceOrigin":a.SourceLocations[&hir.Block{}]=hir.SourceLocation{Unit:"copy-region-review.nanz",Line:99};case "policy":b.PointerWalkPolicy[copies[0]]=true};_,e=hir.ValidateMixedCopyRegionChoices(a,b,choice);fmt.Println(kind,"accepted",e==nil,"err",e)}}
func must(e error){if e!=nil{panic(e)}}
